#pragma once

// Small anti-aliased 2D renderer for the JC3248W535 UI.
//
// Draws into a plain row-major RGB565 buffer (480x320 landscape here) with
// alpha blending: rounded rectangles and rings with smooth edges, 4-bit
// anti-aliased fonts and icons (see ui_assets.h, generated by
// tools/gen_assets.py). No Arduino dependencies, so the very same code also
// builds on a PC for the screenshot preview (tools/preview.cpp).

#include <stdint.h>
#include <stddef.h>

struct UIGlyph {
  uint16_t cp;        // Unicode code point
  uint8_t w, h;       // bitmap size
  int8_t x, y;        // bitmap top-left relative to the pen position on the baseline
  uint8_t adv;        // horizontal advance
  uint32_t off;       // offset into the font's bitmap (4 bit per pixel, rows byte aligned)
};

struct UIFont {
  const UIGlyph* glyphs;   // sorted by code point
  uint16_t count;
  const uint8_t* bits;
  uint8_t line_h, ascent, descent;
};

typedef uint16_t Color;

// 0xRRGGBB -> RGB565
constexpr Color RGB(uint32_t rgb) {
  return (Color)(((rgb >> 8) & 0xF800) | ((rgb >> 5) & 0x07E0) | ((rgb >> 3) & 0x001F));
}

enum UIAlign : uint8_t { ALIGN_LEFT, ALIGN_CENTER, ALIGN_RIGHT };

class UIGfx {
public:
  UIGfx(uint16_t* buf, int w, int h) : _buf(buf), _w(w), _h(h) { resetClip(); }

  int width() const { return _w; }
  int height() const { return _h; }
  uint16_t* buffer() { return _buf; }

  void setClip(int x, int y, int w, int h);
  void resetClip() { _cx0 = 0; _cy0 = 0; _cx1 = _w; _cy1 = _h; }

  static Color blend(Color dst, Color src, uint8_t alpha);   // alpha 0..255
  static Color mix(Color a, Color b, uint8_t t) { return blend(a, b, t); }

  void clear(Color c);
  void fillRect(int x, int y, int w, int h, Color c);
  void blendRect(int x, int y, int w, int h, Color c, uint8_t alpha);
  void vGradient(int x, int y, int w, int h, Color top, Color bottom);

  // anti-aliased shapes
  void fillRoundRect(int x, int y, int w, int h, int r, Color c);
  // filled rounded rect with a 1px border of another colour
  void card(int x, int y, int w, int h, int r, Color fill, Color border);
  void fillCircle(float cx, float cy, float r, Color c);
  // anti-aliased line with round ends
  void line(float x0, float y0, float x1, float y1, float width, Color c);
  void hline(int x, int y, int w, Color c) { fillRect(x, y, w, 1, c); }
  void vline(int x, int y, int h, Color c) { fillRect(x, y, 1, h, c); }
  // ring segment between radii r_in..r_out; angles in degrees, 0 = 3 o'clock,
  // clockwise; round_caps adds half-circle ends
  void arc(float cx, float cy, float r_out, float r_in, float start_deg, float end_deg, Color c, bool round_caps);

  // text: y is the BASELINE; returns the advance width
  // tracking = extra pixels between letters (for spaced-out caps labels)
  int text(const UIFont& f, int x, int y, const char* utf8, Color c, UIAlign align = ALIGN_LEFT, int tracking = 0);
  static int textWidth(const UIFont& f, const char* utf8, int tracking = 0);
  // copies utf8 into dest, cut with "..." so that it fits into max_w pixels
  static void ellipsize(const UIFont& f, const char* utf8, int max_w, char* dest, size_t dest_size);

  // icon glyph (from an icon font) centred on (cx, cy)
  void icon(const UIFont& f, uint16_t cp, int cx, int cy, Color c);

  static const UIGlyph* findGlyph(const UIFont& f, uint32_t cp);
  static int decodeUTF8(const char* s, uint32_t& cp);   // returns bytes consumed (>=1)

private:
  uint16_t* _buf;
  int _w, _h;
  int _cx0, _cy0, _cx1, _cy1;     // clip rect, exclusive end

  inline void plot(int x, int y, Color c, uint8_t a) {
    if (x < _cx0 || y < _cy0 || x >= _cx1 || y >= _cy1 || a == 0) return;
    uint16_t* p = &_buf[y * _w + x];
    *p = a >= 255 ? c : blend(*p, c, a);
  }
  void drawGlyph(const UIFont& f, const UIGlyph& g, int x, int y, Color c);
};
